    /// <summary>
    /// Settings in JSON format for the source and target Microsoft SQL Server endpoint. For information about other available settings, see Extra connection attributes when using SQL Server as a source for DMS and Extra connection attributes when using SQL Server as a tar- get for DMS in the Database Migration Service User Guide. Port -&gt; (integer) Endpoint TCP port. BcpPacketSize -&gt; (integer) The maximum size of the packets (in bytes) used to transfer data using BCP. DatabaseName -&gt; (string) Database name for the endpoint. ControlTablesFileGroup -&gt; (string) Specifies a file group for the DMS internal tables. When the replication task starts, all the internal DMS control tables ( awsdms_ apply_exception, awsdms_apply, awsdms_changes) are created for the specified file group. Password -&gt; (string) Endpoint connection password. QuerySingleAlwaysOnNode -&gt; (boolean) Cleans and recreates table metadata information on the replica- tion instance when a mismatch occurs. An example is a situation where running an alter DDL statement on a table might result in different information about the table cached in the replication instance. ReadBackupOnly -&gt; (boolean) When this attribute is set to Y , DMS only reads changes from transaction log backups and doesn't read from the active trans- action log file during ongoing replication. Setting this parame- ter to Y enables you to control active transaction log file growth during full load and ongoing replication tasks. However, it can add some source latency to ongoing replication. SafeguardPolicy -&gt; (string) Use this attribute to minimize the need to access the backup log and enable DMS to prevent truncation using one of the following two methods. Start transactions in the database: This is the default method. When this method is used, DMS prevents TLOG trunca- tion by mimicking a transaction in the database. As long as such a transaction is open, changes that appear after the transaction started aren't truncated. If you need Microsoft Replication to be enabled in your database, then you must choose this method. Exclusively use sp_repldone within a single task : When this method is used, DMS reads the changes and then uses sp_re- pldone to mark the TLOG transactions as ready for truncation. Although this method doesn't involve any transactional activ- ities, it can only be used when Microsoft Replication isn't running. Also, when using this method, only one DMS task can access the database at any given time. Therefore, if you need to run parallel DMS tasks against the same database, use the default method. Possible values: o rely-on-sql-server-replication-agent o exclusive-automatic-truncation o shared-automatic-truncation ServerName -&gt; (string) Fully qualified domain name of the endpoint. For an Amazon RDS SQL Server instance, this is the output of DescribeDBInstances , in the `` Endpoint .Address`` field. Username -&gt; (string) Endpoint connection user name. UseBcpFullLoad -&gt; (boolean) Use this to attribute to transfer data for full-load operations using BCP. When the target table contains an identity column that does not exist in the source table, you must disable the use BCP for loading table option. UseThirdPartyBackupDevice -&gt; (boolean) When this attribute is set to Y , DMS processes third-party transaction log backups if they are created in native format. SecretsManagerAccessRoleArn -&gt; (string) The full Amazon Resource Name (ARN) of the IAM role that speci- fies DMS as the trusted entity and grants the required permis- sions to access the value in SecretsManagerSecret . The role must allow the iam:PassRole action. SecretsManagerSecret has the value of the Amazon Web Services Secrets Manager secret that al- lows access to the SQL Server endpoint. NOTE: You can specify one of two sets of values for these permis- sions. You can specify the values for this setting and Se- cretsManagerSecretId . Or you can specify clear-text values for UserName , Password , ServerName , and Port . You can't specify both. For more information on creating this Secrets- ManagerSecret and the SecretsManagerAccessRoleArn and Se- cretsManagerSecretId required to access it, see Using secrets to access Database Migration Service resources in the Data- base Migration Service User Guide . SecretsManagerSecretId -&gt; (string) The full ARN, partial ARN, or friendly name of the SecretsMan- agerSecret that contains the SQL Server endpoint connection de- tails. TrimSpaceInChar -&gt; (boolean) Use the TrimSpaceInChar source endpoint setting to right-trim data on CHAR and NCHAR data types during migration. Setting TrimSpaceInChar does not left-trim data. The default value is true . TlogAccessMode -&gt; (string) Indicates the mode used to fetch CDC data. Possible values: o BackupOnly o PreferBackup o PreferTlog o TlogOnly ForceLobLookup -&gt; (boolean) Forces LOB lookup on inline LOB. AuthenticationMethod -&gt; (string) Specifies the authentication method to be used with Microsoft SQL Server. Possible values: o password o kerberos Shorthand Syntax: Port=integer,BcpPacketSize=integer,DatabaseName=string,ControlTablesFileGroup=string,Password=string,QuerySingleAlwaysOnNode=boolean,ReadBackupOnly=boolean,SafeguardPolicy=string,ServerName=string,Username=string,UseBcpFullLoad=boolean,UseThirdPartyBackupDevice=boolean,SecretsManagerAccessRoleArn=string,SecretsManagerSecretId=string,TrimSpaceInChar=boolean,TlogAccessMode=string,ForceLobLookup=boolean,AuthenticationMethod=string JSON Syntax: { "Port": integer, "BcpPacketSize": integer, "DatabaseName": "string", "ControlTablesFileGroup": "string", "Password": "string", "QuerySingleAlwaysOnNode": true|false, "ReadBackupOnly": true|false, "SafeguardPolicy": "rely-on-sql-server-replication-agent"|"exclusive-automatic-truncation"|"shared-automatic-truncation", "ServerName": "string", "Username": "string", "UseBcpFullLoad": true|false, "UseThirdPartyBackupDevice": true|false, "SecretsManagerAccessRoleArn": "string", "SecretsManagerSecretId": "string", "TrimSpaceInChar": true|false, "TlogAccessMode": "BackupOnly"|"PreferBackup"|"PreferTlog"|"TlogOnly", "ForceLobLookup": true|false, "AuthenticationMethod": "password"|"kerberos" }
    /// </summary>
    [CliOption("--microsoft-sql-server-settings")]
    public string? MicrosoftSqlServerSettings { get; set; }

    /// <summary>
    /// Settings in JSON format for the source IBM Db2 LUW endpoint. For in- formation about other available settings, see Extra connection at- tributes when using Db2 LUW as a source for DMS in the Database Mi- gration Service User Guide. DatabaseName -&gt; (string) Database name for the endpoint. Password -&gt; (string) Endpoint connection password. Port -&gt; (integer) Endpoint TCP port. The default value is 50000. ServerName -&gt; (string) Fully qualified domain name of the endpoint. SetDataCaptureChanges -&gt; (boolean) Enables ongoing replication (CDC) as a BOOLEAN value. The de- fault is true. CurrentLsn -&gt; (string) For ongoing replication (CDC), use CurrentLSN to specify a log sequence number (LSN) where you want the replication to start. MaxKBytesPerRead -&gt; (integer) Maximum number of bytes per read, as a NUMBER value. The default is 64 KB. Username -&gt; (string) Endpoint connection user name. SecretsManagerAccessRoleArn -&gt; (string) The full Amazon Resource Name (ARN) of the IAM role that speci- fies DMS as the trusted entity and grants the required permis- sions to access the value in SecretsManagerSecret . The role must allow the iam:PassRole action. SecretsManagerSecret has the value of the Amazon Web Services Secrets Manager secret that al- lows access to the Db2 LUW endpoint. NOTE: You can specify one of two sets of values for these permis- sions. You can specify the values for this setting and Se- cretsManagerSecretId . Or you can specify clear-text values for UserName , Password , ServerName , and Port . You can't specify both. For more information on creating this Secrets- ManagerSecret and the SecretsManagerAccessRoleArn and Se- cretsManagerSecretId required to access it, see Using secrets to access Database Migration Service resources in the Data- base Migration Service User Guide . SecretsManagerSecretId -&gt; (string) The full ARN, partial ARN, or friendly name of the SecretsMan- agerSecret that contains the Db2 LUW endpoint connection de- tails. LoadTimeout -&gt; (integer) The amount of time (in milliseconds) before DMS times out opera- tions performed by DMS on the Db2 target. The default value is 1200 (20 minutes). WriteBufferSize -&gt; (integer) The size (in KB) of the in-memory file write buffer used when generating .csv files on the local disk on the DMS replication instance. The default value is 1024 (1 MB). MaxFileSize -&gt; (integer) Specifies the maximum size (in KB) of .csv files used to trans- fer data to Db2 LUW. KeepCsvFiles -&gt; (boolean) If true, DMS saves any .csv files to the Db2 LUW target that were used to replicate data. DMS uses these files for analysis and troubleshooting. The default value is false. Shorthand Syntax: DatabaseName=string,Password=string,Port=integer,ServerName=string,SetDataCaptureChanges=boolean,CurrentLsn=string,MaxKBytesPerRead=integer,Username=string,SecretsManagerAccessRoleArn=string,SecretsManagerSecretId=string,LoadTimeout=integer,WriteBufferSize=integer,MaxFileSize=integer,KeepCsvFiles=boolean JSON Syntax: { "DatabaseName": "string", "Password": "string", "Port": integer, "ServerName": "string", "SetDataCaptureChanges": true|false, "CurrentLsn": "string", "MaxKBytesPerRead": integer, "Username": "string", "SecretsManagerAccessRoleArn": "string", "SecretsManagerSecretId": "string", "LoadTimeout": integer, "WriteBufferSize": integer, "MaxFileSize": integer, "KeepCsvFiles": true|false }
    /// </summary>
    [CliOption("--ibm-db2-settings")]
    public string? IbmDb2Settings { get; set; }

    /// <summary>
    /// A friendly name for the resource identifier at the end of the End- pointArn response parameter that is returned in the created Endpoint object. The value for this parameter can have up to 31 characters. It can contain only ASCII letters, digits, and hyphen ('-'). Also, it can't end with a hyphen or contain two consecutive hyphens, and can only begin with a letter, such as Example-App-ARN1 . For exam- ple, this value might result in the EndpointArn value arn:aws:dms:eu-west-1:012345678901:rep:Example-App-ARN1 . If you don't specify a ResourceIdentifier value, DMS generates a default identifier value for the end of EndpointArn .
    /// </summary>
    [CliOption("--resource-identifier")]
    public string? ResourceIdentifier { get; set; }

    /// <summary>
    /// Provides information that defines a DocumentDB endpoint. Username -&gt; (string) The user name you use to access the DocumentDB source endpoint. Password -&gt; (string) The password for the user account you use to access the Docu- mentDB source endpoint. ServerName -&gt; (string) The name of the server on the DocumentDB source endpoint. Port -&gt; (integer) The port value for the DocumentDB source endpoint. DatabaseName -&gt; (string) The database name on the DocumentDB source endpoint. NestingLevel -&gt; (string) Specifies either document or table mode. Default value is "none" . Specify "none" to use document mode. Specify "one" to use table mode. Possible values: o none o one ExtractDocId -&gt; (boolean) Specifies whether the document ID is added to the target table. Use this setting when NestingLevel is set to "none" . Set ExtractDocId to true when using multi-document transactions with CDC. Default value is false . DocsToInvestigate -&gt; (integer) Indicates the number of documents to preview to determine the document organization. Use this setting when NestingLevel is set to "one" . Must be a positive value greater than 0 . Default value is 1000 . KmsKeyId -&gt; (string) The KMS key identifier that is used to encrypt the content on the replication instance. If you don't specify a value for the KmsKeyId parameter, then DMS uses your default encryption key. KMS creates the default encryption key for your Amazon Web Ser- vices account. Your Amazon Web Services account has a different default encryption key for each Amazon Web Services Region. SecretsManagerAccessRoleArn -&gt; (string) The full Amazon Resource Name (ARN) of the IAM role that speci- fies DMS as the trusted entity and grants the required permis- sions to access the value in SecretsManagerSecret . The role must allow the iam:PassRole action. SecretsManagerSecret has the value of the Amazon Web Services Secrets Manager secret that al- lows access to the DocumentDB endpoint. NOTE: You can specify one of two sets of values for these permis- sions. You can specify the values for this setting and Se- cretsManagerSecretId . Or you can specify clear-text values for UserName , Password , ServerName , and Port . You can't specify both. For more information on creating this Secrets- ManagerSecret and the SecretsManagerAccessRoleArn and Se- cretsManagerSecretId required to access it, see Using secrets to access Database Migration Service resources in the Data- base Migration Service User Guide . SecretsManagerSecretId -&gt; (string) The full ARN, partial ARN, or friendly name of the SecretsMan- agerSecret that contains the DocumentDB endpoint connection de- tails. UseUpdateLookUp -&gt; (boolean) If true , DMS retrieves the entire document from the DocumentDB source during migration. This may cause a migration failure if the server response exceeds bandwidth limits. To fetch only up- dates and deletes during migration, set this parameter to false . ReplicateShardCollections -&gt; (boolean) If true , DMS replicates data to shard collections. DMS only uses this setting if the target endpoint is a DocumentDB elastic cluster. When this setting is true , note the following: o You must set TargetTablePrepMode to nothing . o DMS automatically sets useUpdateLookup to false . Shorthand Syntax: Username=string,Password=string,ServerName=string,Port=integer,DatabaseName=string,NestingLevel=string,ExtractDocId=boolean,DocsToInvestigate=integer,KmsKeyId=string,SecretsManagerAccessRoleArn=string,SecretsManagerSecretId=string,UseUpdateLookUp=boolean,ReplicateShardCollections=boolean JSON Syntax: { "Username": "string", "Password": "string", "ServerName": "string", "Port": integer, "DatabaseName": "string", "NestingLevel": "none"|"one", "ExtractDocId": true|false, "DocsToInvestigate": integer, "KmsKeyId": "string", "SecretsManagerAccessRoleArn": "string", "SecretsManagerSecretId": "string", "UseUpdateLookUp": true|false, "ReplicateShardCollections": true|false }
    /// </summary>
    [CliOption("--doc-db-settings")]
    public string? DocDbSettings { get; set; }

    /// <summary>
    /// Settings in JSON format for the target Redis endpoint. ServerName -&gt; (string) [required] Fully qualified domain name of the endpoint. Port -&gt; (integer) [required] Transmission Control Protocol (TCP) port for the endpoint. SslSecurityProtocol -&gt; (string) The connection to a Redis target endpoint using Transport Layer Security (TLS). Valid values include plaintext and ssl-encryp- tion . The default is ssl-encryption . The ssl-encryption option makes an encrypted connection. Optionally, you can identify an Amazon Resource Name (ARN) for an SSL certificate authority (CA) using the SslCaCertificateArn setting. If an ARN isn't given for a CA, DMS uses the Amazon root CA. The plaintext option doesn't provide Transport Layer Security (TLS) encryption for traffic between endpoint and database. Possible values: o plaintext o ssl-encryption AuthType -&gt; (string) The type of authentication to perform when connecting to a Redis target. Options include none , auth-token , and auth-role . The auth-token option requires an AuthPassword value to be provided. The auth-role option requires AuthUserName and AuthPassword val- ues to be provided. Possible values: o none o auth-role o auth-token AuthUserName -&gt; (string) The user name provided with the auth-role option of the AuthType setting for a Redis target endpoint. AuthPassword -&gt; (string) The password provided with the auth-role and auth-token options of the AuthType setting for a Redis target endpoint. SslCaCertificateArn -&gt; (string) The Amazon Resource Name (ARN) for the certificate authority (CA) that DMS uses to connect to your Redis target endpoint. Shorthand Syntax: ServerName=string,Port=integer,SslSecurityProtocol=string,AuthType=string,AuthUserName=string,AuthPassword=string,SslCaCertificateArn=string JSON Syntax: { "ServerName": "string", "Port": integer, "SslSecurityProtocol": "plaintext"|"ssl-encryption", "AuthType": "none"|"auth-role"|"auth-token", "AuthUserName": "string", "AuthPassword": "string", "SslCaCertificateArn": "string" }
    /// </summary>
    [CliOption("--redis-settings")]
    public string? RedisSettings { get; set; }

    /// <summary>
    /// Settings in JSON format for the source GCP MySQL endpoint. AfterConnectScript -&gt; (string) Specifies a script to run immediately after DMS connects to the endpoint. The migration task continues running regardless if the SQL statement succeeds or fails. For this parameter, provide the code of the script itself, not the name of a file containing the script. CleanSourceMetadataOnMismatch -&gt; (boolean) Cleans and recreates table metadata information on the replica- tion instance when a mismatch occurs. For example, in a situa- tion where running an alter DDL on the table could result in different information about the table cached in the replication instance. DatabaseName -&gt; (string) Database name for the endpoint. For a MySQL source or target endpoint, don't explicitly specify the database using the Data- baseName request parameter on either the CreateEndpoint or Modi- fyEndpoint API call. Specifying DatabaseName when you create or modify a MySQL endpoint replicates all the task tables to this single database. For MySQL endpoints, you specify the database only when you specify the schema in the table-mapping rules of the DMS task. EventsPollInterval -&gt; (integer) Specifies how often to check the binary log for new changes/events when the database is idle. The default is five seconds. Example: eventsPollInterval=5; In the example, DMS checks for changes in the binary logs every five seconds. TargetDbType -&gt; (string) Specifies where to migrate source tables on the target, either to a single database or multiple databases. Example: targetDbType=MULTIPLE_DATABASES Possible values: o specific-database o multiple-databases MaxFileSize -&gt; (integer) Specifies the maximum size (in KB) of any .csv file used to transfer data to a MySQL-compatible database. Example: maxFileSize=512 ParallelLoadThreads -&gt; (integer) Improves performance when loading data into the MySQL-compatible target database. Specifies how many threads to use to load the data into the MySQL-compatible target database. Setting a large number of threads can have an adverse effect on database perfor- mance, because a separate connection is required for each thread. The default is one. Example: parallelLoadThreads=1 Password -&gt; (string) Endpoint connection password. Port -&gt; (integer) Endpoint TCP port. ServerName -&gt; (string) The MySQL host name. ServerTimezone -&gt; (string) Specifies the time zone for the source MySQL database. Example: serverTimezone=US/Pacific; Note: Do not enclose time zones in single quotes. Username -&gt; (string) Endpoint connection user name. SecretsManagerAccessRoleArn -&gt; (string) The full Amazon Resource Name (ARN) of the IAM role that speci- fies DMS as the trusted entity and grants the required permis- sions to access the value in SecretsManagerSecret. The role must allow the iam:PassRole action. SecretsManagerSecret has the value of the Amazon Web Services Secrets Manager secret that al- lows access to the MySQL endpoint. NOTE: You can specify one of two sets of values for these permis- sions. You can specify the values for this setting and Se- cretsManagerSecretId . Or you can specify clear-text values for UserName , Password , ServerName , and Port . You can't specify both. For more information on creating this Secrets- ManagerSecret and the SecretsManagerAccessRoleArn and Se- cretsManagerSecretId required to access it, see Using secrets to access Database Migration Service resources in the Data- base Migration Service User Guide. SecretsManagerSecretId -&gt; (string) The full ARN, partial ARN, or friendly name of the SecretsMan- agerSecret that contains the MySQL endpoint connection details. Shorthand Syntax: AfterConnectScript=string,CleanSourceMetadataOnMismatch=boolean,DatabaseName=string,EventsPollInterval=integer,TargetDbType=string,MaxFileSize=integer,ParallelLoadThreads=integer,Password=string,Port=integer,ServerName=string,ServerTimezone=string,Username=string,SecretsManagerAccessRoleArn=string,SecretsManagerSecretId=string JSON Syntax: { "AfterConnectScript": "string", "CleanSourceMetadataOnMismatch": true|false, "DatabaseName": "string", "EventsPollInterval": integer, "TargetDbType": "specific-database"|"multiple-databases", "MaxFileSize": integer, "ParallelLoadThreads": integer, "Password": "string", "Port": integer, "ServerName": "string", "ServerTimezone": "string", "Username": "string", "SecretsManagerAccessRoleArn": "string", "SecretsManagerSecretId": "string" }
    /// </summary>
    [CliOption("--gcp-my-sql-settings")]
    public string? GcpMySqlSettings { get; set; }

    /// <summary>
    /// Settings in JSON format for the target Amazon Timestream endpoint. DatabaseName -&gt; (string) [required] Database name for the endpoint. MemoryDuration -&gt; (integer) [required] Set this attribute to specify the length of time to store all of the tables in memory that are migrated into Amazon Timestream from the source database. Time is measured in units of hours. When Timestream data comes in, it first resides in memory for the specified duration, which allows quick access to it. MagneticDuration -&gt; (integer) [required] Set this attribute to specify the default magnetic duration ap- plied to the Amazon Timestream tables in days. This is the num- ber of days that records remain in magnetic store before being discarded. For more information, see Storage in the Amazon Timestream Developer Guide . CdcInsertsAndUpdates -&gt; (boolean) Set this attribute to true to specify that DMS only applies in- serts and updates, and not deletes. Amazon Timestream does not allow deleting records, so if this value is false , DMS nulls out the corresponding record in the Timestream database rather than deleting it. EnableMagneticStoreWrites -&gt; (boolean) Set this attribute to true to enable memory store writes. When this value is false , DMS does not write records that are older in days than the value specified in MagneticDuration , because Amazon Timestream does not allow memory writes by default. For more information, see Storage in the Amazon Timestream Developer Guide . Shorthand Syntax: DatabaseName=string,MemoryDuration=integer,MagneticDuration=integer,CdcInsertsAndUpdates=boolean,EnableMagneticStoreWrites=boolean JSON Syntax: { "DatabaseName": "string", "MemoryDuration": integer, "MagneticDuration": integer, "CdcInsertsAndUpdates": true|false, "EnableMagneticStoreWrites": true|false }
    /// </summary>
    [CliOption("--timestream-settings")]
    public string? TimestreamSettings { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

}
